///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnInit = async function () {
    /* sdd-asis-lifecycle:begin fnInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates(' + "1" + ')');
    await scwin.fnSearchInit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.closeDetail();
    const searchForm = $('#searchForm');
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_FileDownReq").set("method", "searchIRMaterials");
    $c.util.getComponent("dma_FileDownReq").set("forward", "searchirmaterials_sub");
    document.searchForm.ajaxSubmit({ ajaxUrl: '/corpgeneral/irroom.do', ajaxCallBack: scwin.fnSearchCallBack });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_resoroomId ipt_attachSeq ipt_attachFileNm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_FileDownReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_FileDownReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_FileDownReq").set("attachFileNm", ipt_attachFileNm);
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd ipt_repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_searchCorpName').setValue(comAbbrv);
    $c.util.getComponent("dma_FileDownReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_FileDownReq").set("searchCodeType", "char");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.detailView
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.detailView = async function (val) {
    /* sdd-asis-lifecycle:begin detailView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("detailContents").setStyle("display", "");
    $c.util.getComponent('ipt_irSeq').setValue(val);
    $c.util.getComponent("dma_FileDownReq").set("method", "searchIRMaterialsDetail");
    $c.util.getComponent("dma_FileDownReq").set("forward", "searchirmaterials_detail");
    await scwin.tx_detailView_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack2
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack2 = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#detailContents").empty().append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.closeDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.closeDetail = function () {
    /* sdd-asis-lifecycle:begin closeDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#detailContents").empty();
    $c.util.getComponent("detailContents").setStyle("display", "none");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            await scwin.fnSearchInit();
        }
    }
    /* sdd-asis-lifecycle:end */
};
